WITH kept_keys AS (SELECT session_id, page FROM web_events EXCEPT SELECT session_id, page FROM web_events WHERE event_type = 'add_to_cart'), kept_rows AS (SELECT s.* FROM web_events s JOIN kept_keys k ON s.session_id = k.session_id AND s.page = k.page) SELECT DATE_TRUNC('QUARTER', event_time) AS quarter_start, COUNT(*) AS cnt, BIT_AND(duration_sec) AS duration_sec_bit_and, APPROX_PERCENTILE(duration_sec, 0.95) AS duration_sec_p95, MIN(event_time) AS first_event_time, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM kept_rows GROUP BY 1 ORDER BY duration_sec_bit_and DESC NULLS FIRST;
